$ErrorActionPreference='Stop'
$project=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../..'))
. "$project/Tool/Client/Framework-Evidence.ps1";. "$project/Tool/Client/Framework-IO.ps1";. "$project/Tool/Client/Framework-NativeAdapter.ps1";. "$project/Tool/Client/Framework-Collector.ps1"
. "$PSScriptRoot/Framework-Fixtures.ps1"
$root=Join-Path $project ('Builds/Tests/D2/PortraitScope-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($root)|Out-Null
$records=@();$matrix=Get-FrameworkMatrix
$core=@('baseline-offline','update-v2','restart-v2','offline-v2','bad-signature','bad-hash','wrong-player-build','wrong-architecture','missing-dll','missing-bundle','tampered-version-table','disk-budget','download-cancel','network-interruption','semantic-version-table','kill-download-partial','kill-rename-before','kill-state-replace-before','kill-state-replace-after','kill-trial-persisted','kill-hotentry-executing','throw-on-start')
$deferred=@('tok-rejection','tok-disconnect','windows-1080x2400','windows-1536x2048','windows-1280x720','windows-1920x1080','windows-2560x1080','windows-720x480','windows-drag','windows-short-scroll','android-rotation','android-ime-rotation','android-inflight-rotation')
function Require($value,[string]$message){if(-not$value){throw $message}}
function Check([string]$name,[scriptblock]$body){try{&$body;$script:records+=@{name=$name;passed=$true};Write-Host "D2_PORTRAIT_PASS $name"}catch{$script:records+=@{name=$name;passed=$false;error=$_.Exception.Message};Write-Host "D2_PORTRAIT_FAIL $name $($_.Exception.Message)"}}
function SameIds($actual,$expected){Require ((($actual|Sort-Object)-join ',') -ceq (($expected|Sort-Object)-join ',')) 'Required case identities differ from the explicit user scope.'}
Check 'Windows requires hot-update core and only two portrait targets' {SameIds @($matrix.cases|Where-Object {$_.required -eq $true -and 'Windows64' -in $_.platforms}|ForEach-Object id) ($core+@('windows-720x1280','windows-1080x1920'))}
Check 'Android retains portrait lifecycle and both specified portrait targets' {SameIds @($matrix.cases|Where-Object {$_.required -eq $true -and 'Android' -in $_.platforms}|ForEach-Object id) ($core+@('android-720x1280','android-1080x1920','android-ime','android-background','android-safe-area','android-short-scroll'))}
Check 'real login-server cases are retained as deferred interfaces not acceptance requirements' {$items=@($matrix.cases|Where-Object kind -ceq 'session');Require ($items.Count -eq 2 -and @($items|Where-Object required -eq $true).Count -eq 0) 'Live login-server verification still required.'}
Check 'every required UI case uses 720x1280 or1080x1920' {foreach($case in $matrix.cases|Where-Object {$_.required -eq $true -and $_.kind -ceq 'ui'}){Require (("$($case.width)x$($case.height)") -cin @('720x1280','1080x1920')) ('Unexpected UI target '+$case.id)}}
Check 'removed cases remain traceable with explicit user exclusion reasons' {foreach($id in $deferred){$case=@($matrix.cases|Where-Object id -CEQ $id);$excluded=@($matrix.excluded|Where-Object id -CEQ $id);Require ($case.Count -eq 1 -and $case[0].required -eq $false -and -not[string]::IsNullOrWhiteSpace($case[0].exclusionReason) -and $excluded.Count -eq 1 -and $excluded[0].status -ceq 'ExcludedByUser') ('Missing explicit exclusion '+$id)}}
Check 'collection plans include exactly current required cases' {$w=New-FrameworkCollectionPlan -Platform Windows64 -RunId scope -PlayerPath 'C:/player/Client.exe' -NativeEvidenceRoot 'C:/n';$a=New-FrameworkCollectionPlan -Platform Android -RunId scope -PlayerPath 'C:/sdk/adb.exe' -NativeEvidenceRoot '/sdcard/a' -DeviceId emulator-5554 -ApplicationId com.sgame.client;Require ($w.cases.Count -eq 24 -and $a.cases.Count -eq 28 -and @($w.cases|Where-Object id -in $deferred).Count -eq 0 -and @($a.cases|Where-Object id -in $deferred).Count -eq 0) 'Collector still schedules deferred cases.'}
Check 'missing required evidence still fails with exactly24 Windows NotRun cases' {$e=New-FrameworkFixtureContext;$r=Get-FrameworkAcceptance $e;Require (-not$r.passed -and @($r.cases|Where-Object status -ceq 'NotRun').Count -eq 24 -and @($r.errors|Where-Object {$_ -like '*tok-rejection*' -or $_ -like '*windows-1280x720*'}).Count -eq 0) 'Missing current cases or excluded cases handled incorrectly.'}
Check 'all22 hot-update and rollback cases remain required on both platforms' {foreach($id in $core){$case=@($matrix.cases|Where-Object id -CEQ $id);Require ($case.Count -eq 1 -and $case[0].required -eq $true -and 'Windows64' -in $case[0].platforms -and 'Android' -in $case[0].platforms) ('Core requirement lost '+$id)}}
Check 'results identify the explicit revised acceptance scope' {$r=Get-FrameworkAcceptance (New-FrameworkFixtureContext);Require ($r.requiredCaseCount -eq 24 -and $r.scopeRevision.id -ceq '2026-11-01-portrait-interface-only') 'Result omits the current scope revision or required count.'}
Write-FrameworkJsonNew (Join-Path $root 'test-result.json') @{evidenceKind='SyntheticUnit';nativeAcceptance=$false;count=$records.Count;passed=(@($records|Where-Object passed -eq $false).Count -eq 0);cases=$records}
Write-Host "D2_PORTRAIT_RECEIPT $root"
if(@($records|Where-Object passed -eq $false).Count){throw 'D2_PORTRAIT_FAILED'}
